def gen(rng):
    def fmt(fs):
        return str(len(fs)) + '\n' + '\n'.join(f'{x} {y} {p}' for x, y, p in fs)
    tests = [fmt([(0, 0, 1)]), fmt([(3, 3, 7), (3, 3, 2)]), fmt([(0, 0, 1), (4, 0, 1), (2, 6, 2)]),
             fmt([(1, 1, 10), (5, 5, 1), (9, 9, 1)]), fmt([(-3, 7, 5)]), fmt([(0, 0, 1), (10, 10, 1)]),
             fmt([(0, 0, 1), (0, 1, 1), (0, 2, 1), (0, 3, 1)])]
    for n in (2, 3, 4, 5, 6, 8):
        for _ in range(4):
            tests.append(fmt([(rng.randint(-6, 6), rng.randint(-6, 6), rng.randint(1, 9)) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([(rng.randint(-3, 3), rng.randint(-3, 3), rng.randint(1, 1000)) for _ in range(8)]))
    N = 100000
    tests.append(fmt([(rng.randint(-10**6, 10**6), rng.randint(-10**6, 10**6), rng.randint(1, 1000)) for _ in range(N)]))
    tests.append(fmt([(rng.choice((-10**6, 10**6)), rng.choice((-10**6, 10**6)), 1000) for _ in range(N)]))
    tests.append(fmt([(rng.randint(-10**6, -10**6 + 5), rng.randint(10**6 - 5, 10**6), rng.randint(1, 1000)) for _ in range(N)]))
    tests.append(fmt([(i - 50000, 50000 - i, 1 + i % 1000) for i in range(N)]))
    return tests
